ruleContent.content:
@js:(function(){
  var d = null;
  try { d = JSON.parse(result); } catch(e){ return ''; }
  if (!d || !d.data) return '';
  var su = d.data.streamURL || [];
  for (var i=0;i<su.length;i++){
    if (su[i] && su[i].status === 1 && !su[i].onlyVIP && su[i].stream) return su[i].stream;
  }
  for (var i=0;i<su.length;i++){
    if (su[i] && su[i].stream) return su[i].stream;
  }
  return '';
})()

ruleExplore.bookUrl:
@js:(function(){
  var k = result.key || result.playlistKey || '';
  if (!k) return '';
  // 榜单: 有 tag/items/titleDetail
  if (result.items || result.tag || result.titleDetail) {
    return 'https://graph.nct.vn/api/v1/playlist/charts/' + k;
  }
  // 歌单: 有 totalSongs 或 listSong
  if (result.totalSongs || result.listSong) {
    return 'https://graph.nct.vn/api/v1/playlist/detail/' + k;
  }
  // 歌曲
  return 'https://graph.nct.vn/api/v1/song/detail/' + k;
})()

